/**
 * Migration helpers shared by the CLI (./migrate.ts), the test setup, and the
 * health check.
 *
 * Migrations are SQL files generated by drizzle-kit from the schema and
 * committed to Git, so every environment builds the database from exactly the
 * same, reviewable statements. They are never applied implicitly on server
 * start -- a financial system's schema changes should be a deliberate step.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { migrate } from 'drizzle-orm/better-sqlite3/migrator';
import type Database from 'better-sqlite3';
import { MIGRATIONS_FOLDER, type Db } from './index';

/** Drizzle records applied migrations here, keyed by the journal timestamp. */
const MIGRATIONS_TABLE = '__drizzle_migrations';

interface JournalEntry {
  idx: number;
  tag: string;
  when: number;
}

export function runMigrations(database: Db, folder = MIGRATIONS_FOLDER): void {
  migrate(database, { migrationsFolder: folder });
}

function readJournal(folder: string): JournalEntry[] {
  const journalPath = join(folder, 'meta', '_journal.json');
  if (!existsSync(journalPath)) return [];
  const parsed = JSON.parse(readFileSync(journalPath, 'utf8')) as { entries?: JournalEntry[] };
  return parsed.entries ?? [];
}

export interface MigrationStatus {
  available: number;
  applied: number;
  pending: string[];
}

/**
 * Compare the committed migration journal with what the database has applied.
 * Mirrors Drizzle's own rule: a migration is pending when its journal timestamp
 * is newer than the most recently applied one.
 */
export function getMigrationStatus(
  sqlite: Database.Database,
  folder = MIGRATIONS_FOLDER,
): MigrationStatus {
  const journal = readJournal(folder);

  const tableExists = sqlite
    .prepare("select 1 from sqlite_master where type = 'table' and name = ?")
    .get(MIGRATIONS_TABLE);

  if (!tableExists) {
    return { available: journal.length, applied: 0, pending: journal.map((e) => e.tag) };
  }

  const row = sqlite
    .prepare(`select count(*) as applied, max(created_at) as latest from ${MIGRATIONS_TABLE}`)
    .get() as { applied: number; latest: number | null };

  const latest = row.latest ?? 0;
  const pending = journal.filter((entry) => entry.when > latest).map((entry) => entry.tag);

  return { available: journal.length, applied: row.applied, pending };
}
